const { exec } = require('node:child_process');

// ❌ OLD: exec buffers ALL stdout into memory. For a command that
// produces a lot of output (a large file, a verbose tool), the
// default maxBuffer (1MB) is exceeded → the child is killed with
// ERR_CHILD_PROCESS_STDIO_MAXBUFFER. Raising maxBuffer just moves the
// limit and spikes memory.
exec('cat hugefile.log', (err, stdout) => {
  if (err) return console.error('failed:', err); // ❌ OLD: maxBuffer hit
  console.log('bytes:', stdout.length); // ❌ OLD: whole output in memory
});

// exec is fine for small outputs (a version string); for anything
// large or long-running, it's the wrong tool.

const { spawn } = require('node:child_process');

// ✅ NEW: spawn streams stdout/stderr — data flows as chunks, no
// buffering limit, memory stays bounded regardless of output size.
const child = spawn('cat', ['hugefile.log']); // ✅ NEW: no shell, args array

child.stdout.on('data', (chunk) => {
  processLine(chunk); // ✅ NEW: process incrementally
});

child.stderr.on('data', (chunk) => {
  console.error('stderr:', chunk.toString());
});

child.on('error', (err) => {
  console.error('failed to spawn:', err); // bad executable, etc.
});

child.on('exit', (code, signal) => {
  console.log('exited', code, signal);
});

